--liquibase formatted sql

--changeset cemeterymapping:503-create-reviewed-passageways splitStatements:false
DO $create$
DECLARE
 cemetery uuid;
 area jsonb;
 outline geometry;
 section_outline geometry;
 existing_lots geometry;
BEGIN
 SELECT id INTO cemetery FROM cemeteries WHERE facility_id='1' AND deleted_at IS NULL;
 IF cemetery IS NULL OR NOT EXISTS(SELECT 1 FROM sections WHERE cemetery_id=cemetery AND name IN('A','B','C','D') AND deleted_at IS NULL) THEN RETURN; END IF;
 PERFORM assert_migration_prerequisite((SELECT count(DISTINCT name)=4 FROM sections WHERE cemetery_id=cemetery AND name IN('A','B','C','D') AND deleted_at IS NULL),
   'Migration 503 requires all four reviewed Trinity sections');
 PERFORM 1 FROM lots WHERE cemetery_id=cemetery AND deleted_at IS NULL ORDER BY id FOR UPDATE;
 SELECT ST_UnaryUnion(ST_Collect(geometry)) INTO existing_lots FROM lots WHERE cemetery_id=cemetery AND deleted_at IS NULL;
 PERFORM assert_migration_prerequisite(NOT EXISTS(SELECT 1 FROM lots WHERE cemetery_id=cemetery AND section_id IN('A','B','C','D') AND lot_id IN('P01','P02','P03') AND deleted_at IS NULL),
   'Migration 503 passageway identifiers must be unused');
 PERFORM set_config('app.audit.source','migration',true);
 PERFORM set_config('app.audit.reason','User approved 2026-10-29: create ten reviewed passageways alongside lots, including the D-P03 western end; preserve existing grave assignments and individual ownership records.',true);
 FOR area IN SELECT value FROM jsonb_array_elements($areas$[{"id":"A-P01","section":"A","lotId":"P01","box":[-80.08004095325644,40.601175733161156,-80.07972179381248,40.60120574985206],"references":[{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Original 2017","cell":"G10","originalText":"Passage 31-53","interpretationNote":"Updated 2022 F16 reverses the pair to 53 and 31 and adds a 10-foot width. The separate F205 row says No evidence in records; preserve that uncertainty."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Original 2017","cell":"G53","originalText":"Passage 33-55","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Original 2017","cell":"G66","originalText":"Passage 34-56","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Original 2017","cell":"G103","originalText":"Passage 35-57","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Original 2017","cell":"G104","originalText":"Passage 36-58","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Original 2017","cell":"G108","originalText":"Passage 37-59","interpretationNote":"2022 contains both the retained interest and the 2021 transfer to another owner. Do not count the rows as separate passageways or assume all sold capacity remains available."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Original 2017","cell":"G127","originalText":"Passage 30 -52","interpretationNote":"Fits