 2022","cell":"F83","originalText":"Passage 40-41","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Updated 2022","cell":"F84","originalText":"Passage 20-42","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Updated 2022","cell":"F113","originalText":"Passage 26-48","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Updated 2022","cell":"F121","originalText":"Passage 87-92","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Updated 2022","cell":"F137","originalText":"Passage 88-93","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Updated 2022","cell":"F138","originalText":"Passage 89-94","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Updated 2022","cell":"F204","originalText":"Passage 29-51","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Updated 2022","cell":"F218","originalText":"Passage 24-46","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Updated 2022","cell":"F228","originalText":"Passage 25-47","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Updated 2022","cell":"F233","originalText":"Passage 22-44","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Updated 2022","cell":"F247","originalText":"Passage 27-49","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Updated 2022","cell":"F248","originalText":"Passage 28-50","interpretationNote":"Fits this corridor\u2019s opposing lot rows. Final gravesite assignments and corridor limits still require review."},{"source":"Trinity Cemetery Registry 2022.xlsx","worksheet":"Updated 2022","cell":"F259","originalText":"Passage 40-41","interpretationNote":"Historical location reference; confirm individual gravesite and deed assignments separately."}]},{"id":"D-P01","section":"D","lotId":"P01","box":[-80.08033120887234,40.60180371185238,-80.08003706144088,40.60182018067059],"references":[]},{"id":"D-P02","section":"D","lotId":"P02","box":[-80.08032679141415,40.60169940933194,-80.08003706144088,40.60171587815045],"references":[]},{"id":"D-P03","section":"D","lotId":"P03","box":[-80.081,40.60159510681121,-80.08016913529498,40.60161157563002],"references":[]}]$areas$::jsonb) LOOP
  SELECT geometry INTO section_outline FROM sections WHERE cemetery_id=cemetery AND name=area->>'section' AND deleted_at IS NULL;
  outline:=ST_MakeEnvelope((area->'box'->>0)::float8,(area->'box'->>1)::float8,(area->'box'->>2)::float8,(area->'box'->>3)::float8,4326);
  outline:=ST_Multi(ST_CollectionExtract(ST_Difference(ST_Intersection(outline,section_outline),COALESCE(existing_lots,ST_GeomFromText('MULTIPOLYGON EMPTY',4326))),3));
  PERFORM assert_migration_prerequisite(NOT ST_IsEmpty(outline) AND ST_IsValid(outline) AND ST_CoveredBy(outline,ST_Buffer(section_outline,1e-12)),
    'Migration 503 requires a nonempty valid passageway inside section: ' || (area->>'id'));
  INSERT INTO lots(cemetery_id,section_uuid,facility_id,section_id,lot_id,name,area_type,location_references,
    geometry,geometry_type,geometry_source,geometry_confidence,geometry_notes)
  SELECT cemetery,section_id,'1',area->>'section',area->>'lotId',area->>'id','passageway',area->'references',
    outline,'operational','Migration 503: user-approved passageway review, 2026-10-29.','estimated',
    'Operational corridor boundary, clipped to the current section and excluding existing active lots. Individual gravesite deeds only; no whole-passageway ownership. Existing gravesite assignments require separate review.'
  FROM sections WHERE cemetery_id=cemetery AND name=area->>'section' AND deleted_at IS NULL;
 END LOOP;
END
$create$;

